    private static void Add(Dictionary<MaterialIconKind, string> target, string aliases, string value)
    {
        foreach (var alias in aliases.Split(' '))
        {
            if (Enum.TryParse<MaterialIconKind>(alias, out var kind)) target[kind] = value;
            if (!alias.EndsWith("Outline", StringComparison.Ordinal) &&
                Enum.TryParse<MaterialIconKind>(alias + "Outline", out var outline)) target.TryAdd(outline, value);
        }
    }
